class FederationManagerShutdownTest {

	@Test
	void shutdownCompletesAndRestoresCallerInterrupt() throws Exception {
		boolean wasInterrupted = Thread.interrupted();
		FedXRepository repository = FedXFactory.newFederation().withMembers(List.of()).create();

		try {
			repository.init();
			Thread.currentThread().interrupt();

			assertDoesNotThrow(repository::shutDown);
			assertFalse(repository.isInitialized(), "shutdown should leave the repository uninitialized");
			assertTrue(Thread.currentThread().isInterrupted(), "shutdown should restore the caller's interrupt status");
		} finally {
			Thread.interrupted();
			if (repository.isInitialized()) {
				repository.shutDown();
			}
			if (wasInterrupted) {
				Thread.currentThread().interrupt();
			}
		}
	}

	@Test
	void shutdownCompletesAndRestoresInterruptArrivingDuringSchedulerWait() throws Exception {
		boolean wasInterrupted = Thread.interrupted();
		FedXRepository repository = FedXFactory.newFederation().withMembers(List.of()).create();

		try {
			repository.init();
			ParallelExecutor<BindingSet> control = mock(ParallelExecutor.class);
			when(control.isFinished()).thenReturn(false);
			when(control.getQueryInfo()).thenReturn(mock(QueryInfo.class));
			CountDownLatch taskStarted = new CountDownLatch(1);
			ParallelTaskBase<BindingSet> task = new ParallelTaskBase<>() {
				@Override
				public ParallelExecutor<BindingSet> getControl() {
					return control;
				}

				@Override
				protected CloseableIteration<BindingSet> performTaskInternal() throws Exception {
					taskStarted.countDown();
					new CountDownLatch(1).await();
					return new EmptyIteration<>();
				}
			};
			repository.getFederationContext().getManager().getJoinScheduler().schedule(task);
			assertTrue(taskStarted.await(5, TimeUnit.SECONDS), "scheduled worker should start before shutdown");

			AtomicReference<Throwable> shutdownFailure = new AtomicReference<>();
			AtomicBoolean shutdownInterrupted = new AtomicBoolean();
			Thread shutdownThread = new Thread(() -> {
				try {
					repository.shutDown();
				} catch (Throwable failure) {
					shutdownFailure.set(failure);
				} finally {
					shutdownInterrupted.set(Thread.currentThread().isInterrupted());
				}
			});
			shutdownThread.start();

			try {
				awaitSchedulerShutdown(shutdownThread);
				shutdownThread.interrupt();
				shutdownThread.join(TimeUnit.SECONDS.toMillis(5));
				assertFalse(shutdownThread.isAlive(), "shutdown should finish after the worker is aborted");
				assertNull(shutdownFailure.get(), "shutdown should not propagate an interruption from a scheduler");
				assertTrue(shutdownInterrupted.get(), "shutdown should restore the caller's interrupt status");
			} finally {
				if (shutdownThread.isAlive()) {
					shutdownThread.interrupt();
				}
			}
		} finally {
			Thread.interrupted();
			assertDoesNotThrow(repository::shutDown);
			if (wasInterrupted) {
				Thread.currentThread().interrupt();
			}
		}
	}

	private static void awaitSchedulerShutdown(Thread shutdownThread) throws InterruptedException {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (System.nanoTime() < deadline) {
			boolean waitingForTermination = Arrays.stream(shutdownThread.getStackTrace())
					.anyMatch(frame -> frame.getClassName().equals("java.util.concurrent.ThreadPoolExecutor")
							&& frame.getMethodName().equals("awaitTermination"));
			if (waitingForTermination) {
				return;
			}
			Thread.sleep(1);
		}
		throw new AssertionError("shutdown should wait for the active join worker");
	}
}
